//! Deterministic **replay** model provider (ADR-0023).
//!
//! Returns recorded responses from a cassette file instead of calling a model, so governed
//! workflows can run offline and reproducibly (acceptance scenarios, demos, CI). It is a
//! production component, but:
//! * it is disabled unless explicitly enabled in configuration;
//! * it reports `Local` egress and zero cost;
//! * the reported model version embeds the cassette's SHA-256, so model usage records and
//!   artifact provenance show that the output was **replayed, not generated by AI**.
//!
//! Cassette (JSON): `{"description": "...", "entries": [{"match": "<text in the system
//! message>", "responses": [{"tool": "<tool>", "input": {...}} | {"json": {...}} |
//! {"text": "..."}]}]}`. The first entry whose `match` occurs in the system message is
//! used; its responses are returned in order (one per model call).

use crate::model::*;
use async_trait::async_trait;
use eaeh_core::{HarnessError, ModelId, ProviderId, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::path::Path;
use std::sync::Mutex;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Cassette {
    #[serde(default)]
    pub description: String,
    pub entries: Vec<CassetteEntry>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct CassetteEntry {
    #[serde(rename = "match")]
    pub matches: String,
    pub responses: Vec<ReplayResponse>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ReplayResponse {
    Tool { tool: String, input: Value },
    Json { json: Value },
    Text { text: String },
}

pub struct ReplayProvider {
    id: ProviderId,
    model: ModelDescriptor,
    cassette: Cassette,
    cursors: Mutex<Vec<usize>>,
}

impl std::fmt::Debug for ReplayProvider {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ReplayProvider (DETERMINISTIC REPLAY, NOT AI)")
            .field("version", &self.model.version)
            .finish()
    }
}

impl ReplayProvider {
    pub fn from_file(path: &Path) -> Result<Self> {
        let bytes = std::fs::read(path)
            .map_err(|e| HarnessError::invalid_input(format!("replay cassette {}: {e}", path.display())))?;
        let cassette: Cassette = serde_json::from_slice(&bytes)
            .map_err(|e| HarnessError::invalid_input(format!("replay cassette {}: {e}", path.display())))?;
        Self::new(cassette, &eaeh_core::hash::sha256_hex(&bytes))
    }

    pub fn new(cassette: Cassette, digest: &str) -> Result<Self> {
        if cassette.entries.is_empty() {
            return Err(HarnessError::invalid_input("replay cassette has no entries"));
        }
        let id = ProviderId::new("replay")?;
        let n = cassette.entries.len();
        Ok(Self {
            model: ModelDescriptor {
                id: ModelId::new("replay")?,
                provider: id.clone(),
                version: format!("replay-cassette-{}", &digest[..digest.len().min(16)]),
                capabilities: ["tools".to_string(), "json".to_string()].into(),
                context_window: 1_000_000,
                max_output_tokens: 128_000,
                input_cost_per_mtok_micros: 0,
                output_cost_per_mtok_micros: 0,
                quality_tier: 0,
                residency: ["local".to_string()].into(),
            },
            id,
            cassette,
            cursors: Mutex::new(vec![0; n]),
        })
    }

    pub fn version(&self) -> &str {
        &self.model.version
    }
}

#[async_trait]
impl ModelProvider for ReplayProvider {
    fn id(&self) -> &ProviderId {
        &self.id
    }
    fn models(&self) -> Vec<ModelDescriptor> {
        vec![self.model.clone()]
    }
    fn egress(&self) -> Egress {
        Egress::Local
    }
    async fn complete(&self, _model: &ModelId, request: &ModelRequest) -> Result<ModelResponse> {
        let system = request
            .messages
            .first()
            .map(|m| m.content.as_str())
            .unwrap_or_default();
        let idx = self
            .cassette
            .entries
            .iter()
            .position(|e| system.contains(&e.matches))
            .ok_or_else(|| {
                HarnessError::invalid_input("replay cassette has no entry matching this agent's instructions")
            })?;
        let resp = {
            let mut c = self
                .cursors
                .lock()
                .map_err(|_| HarnessError::internal("replay cursor lock poisoned"))?;
            let e = &self.cassette.entries[idx];
            let r = e.responses.get(c[idx]).cloned().ok_or_else(|| {
                HarnessError::invalid_input(format!(
                    "replay cassette exhausted for '{}' ({} responses recorded)",
                    e.matches,
                    e.responses.len()
                ))
            })?;
            c[idx] += 1;
            r
        };
        let usage = Usage {
            input_tokens: request
                .messages
                .iter()
                .map(|m| m.content.len() as u64 / 4 + 1)
                .sum(),
            output_tokens: 0,
        };
        let base = |content: String, tool_calls| ModelResponse {
            content,
            tool_calls,
            usage,
            model_version: self.model.version.clone(),
            finish_reason: "replay".into(),
        };
        Ok(match resp {
            ReplayResponse::Tool { tool, input } => {
                base("calling tools".into(), vec![ProposedToolCall { tool, input }])
            }
            ReplayResponse::Json { json } => base(json.to_string(), vec![]),
            ReplayResponse::Text { text } => base(text, vec![]),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn req(system: &str) -> ModelRequest {
        ModelRequest {
            messages: vec![Message {
                role: MessageRole::System,
                content: system.into(),
            }],
            tools: vec![],
            max_output_tokens: 100,
            temperature: None,
        }
    }

    #[tokio::test]
    async fn replays_in_order_per_agent_and_is_labelled() {
        let c: Cassette = serde_json::from_value(serde_json::json!({"entries": [
            {"match": "'analyst' agent", "responses": [{"tool": "knowledge.read", "input": {"document": "a/b@v1"}}, {"json": {"ok": 1}}]},
            {"match": "'architect' agent", "responses": [{"text": "plain"}]}
        ]}))
        .unwrap();
        let p = ReplayProvider::new(c, "0123456789abcdef0123").unwrap();
        assert_eq!(p.egress(), Egress::Local);
        assert_eq!(p.models()[0].input_cost_per_mtok_micros, 0);
        let m = ModelId::new("replay").unwrap();
        let r = p.complete(&m, &req("You are the 'analyst' agent")).await.unwrap();
        assert_eq!(r.tool_calls[0].tool, "knowledge.read");
        assert_eq!(r.model_version, "replay-cassette-0123456789abcdef");
        let r = p
            .complete(&m, &req("You are the 'architect' agent"))
            .await
            .unwrap();
        assert_eq!(r.content, "plain");
        let r = p.complete(&m, &req("You are the 'analyst' agent")).await.unwrap();
        assert_eq!(r.content, "{\"ok\":1}");
        let e = p
            .complete(&m, &req("You are the 'analyst' agent"))
            .await
            .unwrap_err();
        assert!(e.message.contains("exhausted"));
        assert!(
            p.complete(&m, &req("unknown"))
                .await
                .unwrap_err()
                .message
                .contains("no entry matching")
        );
    }
}
